DATABASE_ZIP_PATH = PROJECT_ROOT / "mimic3_deploy_db.zip"

LOGO_PATH = PROJECT_ROOT / "logo.jpg"


def ensure_deployment_database():
    """
    Ensure the deployment DuckDB exists.

    Local development:
        If the database already exists, nothing is changed.

    Streamlit Cloud:
        If the database is absent but the deployment ZIP exists,
        extract the DuckDB automatically.
    """

    if DATABASE_PATH.exists():
        return

    if not DATABASE_ZIP_PATH.exists():
        raise FileNotFoundError(
            "MIMIC-III Explorer database was not found and "
            "the deployment database archive is also missing."
        )

    DATABASE_PATH.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    with zipfile.ZipFile(DATABASE_ZIP_PATH, "r") as archive:
        archive.extractall(DATABASE_PATH.parent)

    if not DATABASE_PATH.exists():
        raise FileNotFoundError(
            "Deployment database archive was extracted, "
            "but mimic3_explorer.duckdb was not created."
        )


ensure_deployment_database()
