# ============================================================
# DuckDB helpers
# ============================================================

def database_exists() -> bool:
    return DATABASE_PATH.exists()


@st.cache_resource
def get_connection() -> duckdb.DuckDBPyConnection:
    """
    Open the Stage12 DuckDB in READ-ONLY mode.
    """

    if not DATABASE_PATH.exists():
        raise FileNotFoundError(
            f"DuckDB database not found:\n{DATABASE_PATH}"
        )

    return duckdb.connect(
        str(DATABASE_PATH),
        read_only=True,
    )


def query_df(
    sql: str,
    params: list[Any] | None = None,
) -> pd.DataFrame:

    con = get_connection()

    if params is None:
        return con.execute(
            sql
        ).fetchdf()

    return con.execute(
        sql,
        params,
    ).fetchdf()


def query_scalar(
    sql: str,
    params: list[Any] | None = None,
) -> Any:

    con = get_connection()

    if params is None:
        row = con.execute(
            sql
        ).fetchone()

    else:
        row = con.execute(
            sql,
            params,
        ).fetchone()

    if row is None:
        return None

    return row[0]


@st.cache_data
def get_columns(
    relation_name: str,
) -> list[str]:

    df = query_df(
        f"""
        DESCRIBE {relation_name}
        """
    )

    return df[
        "column_name"
    ].tolist()


def has_column(
    relation_name: str,
    column_name: str,
) -> bool:

    return (
        column_name
        in get_columns(
            relation_name
        )
    )


# ============================================================
# Formatting helpers
# ============================================================

def format_integer(
    value: Any,
) -> str:

    if value is None:
        return "—"

    try:
        return f"{int(value):,}"
    except Exception:
        return str(value)


def format_float(
    value: Any,
    decimals: int = 2,
) -> str:

    if value is None:
        return "—"

    try:
        return f"{float(value):,.{decimals}f}"
    except Exception:
        return str(value)


def dataframe_to_csv_bytes(
    df: pd.DataFrame,
) -> bytes:

    return df.to_csv(
        index=False
    ).encode(
        "utf-8"
    )


